(()=>{const d=document;const style=d.createElement('style');style.textContent='.buy:disabled{opacity:.38;cursor:not-allowed;box-shadow:none}';d.head.appendChild(style);const head=d.querySelector('.solutionHead');if(head&&!d.getElementById('adjustBanner')){const b=d.createElement('div');b.id='adjustBanner';b.className='noteBox hidden';b.style.margin='16px 0 0';head.after(b)}const cold=d.getElementById('coldCard'),topical=d.getElementById('topicalCard');if(cold&&!d.getElementById('coldKeepCard'))cold.insertAdjacentHTML('afterend','<div class="block hidden" id="coldKeepCard"><div class="prodtag">2 · Recovery component • KEEP</div><div class="product"><div class="pimage"><div class="fallbackProduct"><b>Your cold option</b><span>Existing item / home method</span></div></div><div><span class="rolepill">No new purchase needed</span><div class="prodname" id="coldKeepName">Use the cold option you already have</div><div><span class="price">$0</span><span class="sizepill">KEEP</span></div><ul class="reasonlist"><li>Keneflex is treating recovery as a role to fill—not a SKU it must sell.</li><li>We would confirm condition, safe application and whether your option can perform that role.</li><li>If it clears those checks, your existing option beats another sale.</li></ul><div class="productActions"><button class="miniBtn" data-tune="cold-buy">I’d rather buy the recommended wrap</button><button class="miniBtn" data-tune="cold-remove">I don’t value this role</button></div></div></div></div>');if(topical&&!d.getElementById('topicalKeepCard'))topical.insertAdjacentHTML('afterend','<div class="block hidden" id="topicalKeepCard"><div class="prodtag">3 · Comfort component • KEEP</div><div class="product"><div class="pimage"><div class="fallbackProduct"><b>Your topical</b><span>Existing product</span></div></div><div><span class="rolepill">No new purchase needed</span><div class="prodname">Use your current topical if it is appropriate</div><div><span class="price">$0</span><span class="sizepill">KEEP</span></div><ul class="reasonlist"><li>Keneflex should verify what you use, the label directions and compatibility before accepting it as the substitute.</li><li>If it safely fills the same comfort role, there is no reason to duplicate the purchase.</li></ul><div class="productActions"><button class="miniBtn" data-tune="topical-buy">I’d rather buy the recommended topical</button><button class="miniBtn" data-tune="topical-remove">I don’t want a topical</button></div></div></div></div>');const originalApply=applySet;applySet=function(str){originalApply(str);if(str==='existing:cold'){state.components.cold=true;state.substitutions.cold=true}if(str==='existing:topical'){state.components.topical=true;state.substitutions.topical=true}};refreshSolution=function(){d.getElementById('metaLoc').textContent=locLabel();d.getElementById('metaPattern').textContent=timingLabel()+' • '+symptomLabel();d.getElementById('metaActivity').textContent=capitalize(state.activity||'activity');d.getElementById('metaFit').textContent=state.wrist.toFixed(1)+' in • '+(state.stability==='flex'?'movement-first':'stability-first');d.getElementById('coldCard').classList.toggle('hidden',!state.components.cold||state.substitutions.cold);d.getElementById('coldKeepCard').classList.toggle('hidden',!state.components.cold||!state.substitutions.cold);d.getElementById('topicalCard').classList.toggle('hidden',!state.components.topical||state.substitutions.topical);d.getElementById('topicalKeepCard').classList.toggle('hidden',!state.components.topical||!state.substitutions.topical);updateTotal()};updateTotal=function(){let paid=(state.components.support?1:0)+(state.components.cold&&!state.substitutions.cold?1:0)+(state.components.topical&&!state.substitutions.topical?1:0);d.getElementById('solutionTotal').textContent='$'+total().toFixed(2);let notes=[];if(state.substitutions.cold)notes.push('using your cold option');if(state.substitutions.topical)notes.push('using your topical');d.getElementById('solutionSummary').textContent=(paid?paid+' purchased component'+(paid===1?'':'s'):'no new products')+' + self-care plan'+(notes.length?' • '+notes.join(' • '):'');const stat=d.getElementById('solutionStatus'),cart=d.getElementById('cartBtn');if(!state.components.support){stat.textContent='Core activity-support goal no longer fully addressed';stat.className='solutionStatus statusWarn';cart.disabled=true;cart.textContent='Rebuild needed before cart'}else{stat.textContent='Complete solution';stat.className='solutionStatus statusGood';cart.disabled=false;cart.textContent='Put what I need in my cart →'}};result=function(msg){const modal=d.getElementById('tuneResult'),banner=d.getElementById('adjustBanner');modal.innerHTML=msg;modal.classList.remove('hidden');banner.innerHTML='<b>Keneflex rebuilt your solution.</b><br>'+msg;banner.classList.remove('hidden');refreshSolution();setTimeout(()=>banner.scrollIntoView({behavior:'smooth',block:'start'}),50)};const originalTune=handleTune;handleTune=function(action){if(action==='cold-buy'){state.components.cold=true;state.substitutions.cold=false;result('<b>Added back.</b> The Polar wrap is again the recovery purchase in your solution.');closeModals();return}if(action==='topical-buy'){state.components.topical=true;state.substitutions.topical=false;result('<b>Added back.</b> Biofreeze is again the optional comfort purchase in your solution.');closeModals();return}originalTune(action)};refreshSolution()})();